1	import { useQuery } from "@tanstack/react-query";
2	import { useLocation } from "wouter";
3	import { propFetch } from "@/lib/property-api";
4	import { StatCarousel } from "./stat-carousel";
5	import { motion } from "framer-motion";
6	import { PopIn } from "@/components/pop-in";
7	
8	/* ── Design tokens ── */
9	const C = {
10	  navy:  '#040D6D',
11	  sky:   '#58ABFF',
12	  btn:   '#3F9BFF',
13	  white: '#FFFFFF',
14	  mute:  '#8C8C8C',
15	};
16	
17	const STATUS_MAP: Record<string, { dot: string; bg: string; fg: string; label: string }> = {
18	  paid:     { dot: '#13C29A', bg: 'rgba(19,194,154,0.14)',  fg: '#0B7D63', label: 'paid' },
19	  overdue:  { dot: '#FF3B4E', bg: 'rgba(255,59,78,0.12)',   fg: '#C71A2A', label: 'overdue' },
20	  failed:   { dot: '#FF8A00', bg: 'rgba(255,138,0,0.14)',   fg: '#B25A00', label: 'not delivered' },
21	  dueSoon:  { dot: '#FFB02E', bg: 'rgba(255,176,46,0.18)',  fg: '#9A6A00', label: 'due soon' },
22	  upcoming: { dot: '#3F9BFF', bg: 'rgba(63,155,255,0.16)',  fg: '#1A5FCC', label: 'upcoming' },
23	};
24	
25	const GLASS = {
26	  background: 'linear-gradient(140deg, rgba(255,255,255,0.92) 0%, rgba(234,238,244,0.72) 50%, rgba(220,227,240,0.62) 100%)',
27	  backdropFilter: 'blur(16px) saturate(130%)',
28	  WebkitBackdropFilter: 'blur(16px) saturate(130%)',
29	  border: '1px solid rgba(255,255,255,0.7)',
30	  boxShadow: '0 12px 32px rgba(4,13,109,0.10), inset 0 1px 0 rgba(255,255,255,0.95)',
31	} as React.CSSProperties;
32	
33	/** Shared lift-on-hover / press-on-tap for dashboard boxes. */
34	const HOVER = {
35	  whileHover: { y: -2, transition: { duration: 0.18, ease: [0.34, 1.56, 0.64, 1] as const } },
36	  whileTap: { scale: 0.98 },
37	} as const;
38	
39	/* ── Helpers ── */
40	function fmtCents(c: number) { return '$' + (c / 100).toLocaleString('en-NZ', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
41	
42	function invoiceStatus(inv: any): string {
43	  if (inv.status === 'paid' || inv.status === 'paid_external') return 'paid';
44	  if (inv.status === 'overdue') return 'overdue';
45	  if (inv.status === 'dispatch_failed') return 'failed';
46	  return 'upcoming';
47	}
48	
49	/* ── Status badge ── */
50	function StatusBox({ status }: { status: string }) {
51	  const s = STATUS_MAP[status] ?? STATUS_MAP.upcoming;
52	  return (
53	    <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '4px 9px', borderRadius: 8, background: s.bg, color: s.fg, fontWeight: 600, fontSize: 9.5, letterSpacing: '0.06em', textTransform: 'uppercase' }}>
54	      <span style={{ width: 6, height: 6, borderRadius: 999, background: s.dot, flexShrink: 0 }} />
55	      {s.label}
56	    </div>
57	  );
58	}
59	
60	/* ── Collection gauge ── */
61	function Ring({ pct }: { pct: number }) {
62	  const cx = 65, cy = 65, r = 48, diskR = 37;
63	  const circ = 2 * Math.PI * r;
64	  const p = Math.max(0.01, Math.min(1, pct));
65	  const endAng = (135 + 360 * p) * Math.PI / 180;
66	  return (
67	    <svg width="130" height="130" viewBox="0 0 130 130" style={{ display: 'block' }}>
68	      <defs>
69	        <filter id="pg-disk" x="-90%" y="-90%" width="280%" height="280%">
70	          <feDropShadow dx="0" dy="2.5" stdDeviation="7" floodColor="rgba(4,13,109,0.22)" />
71	        </filter>
72	        <filter id="pg-arc" x="-80%" y="-80%" width="260%" height="260%">
73	          <feDropShadow dx="0" dy="0.5" stdDeviation="4" floodColor="#040D6D" floodOpacity="0.32" />
74	        </filter>
75	      </defs>
76	      <circle cx={cx} cy={cy} r={diskR} fill="#EAEAEA" filter="url(#pg-disk)" />
77	      <circle cx={cx} cy={cy} r={r} fill="none" stroke="#FFFFFF" strokeOpacity="0.8" strokeWidth="1.5" />
78	      <circle cx={cx} cy={cy} r={r} fill="none" stroke={C.navy} strokeWidth="2.5" strokeLinecap="round"
79	        strokeDasharray={`${circ * p} ${circ}`} transform={`rotate(135 ${cx} ${cy})`} filter="url(#pg-arc)" />
80	      <circle cx={cx + r * Math.cos(endAng)} cy={cy + r * Math.sin(endAng)} r="5.5" fill={C.navy} filter="url(#pg-arc)" />
81	      <text x={cx} y={cy + 6} textAnchor="middle" fontFamily="system-ui,sans-serif" fontWeight="400" fontSize="19" fill={C.navy}>
82	        {Math.round(p * 100)}%
83	      </text>
84	    </svg>
85	  );
86	}
87	
88	/* ── Stat icon SVGs ── */
89	function IcoTenants({ c = C.navy }: { c?: string }) {
90	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={c}><circle cx="8.5" cy="8" r="3"/><circle cx="16" cy="8.5" r="2.4"/><path d="M2.6 19c0-3.2 2.6-5.6 5.9-5.6s5.9 2.4 5.9 5.6z"/><path d="M15.4 13.6c2.6.2 4.9 2.3 4.9 5.1"/></svg>;
91	}
92	function IcoWarn({ c = C.navy }: { c?: string }) {
93	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round"><path d="M12 3.6 21 19H3z"/><path d="M12 10v4.1"/><circle cx="12" cy="16.6" r=".95" fill={c} stroke="none"/></svg>;
94	}
95	function IcoPage({ c = C.navy }: { c?: string }) {
96	  return <svg width={17} height={17} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth="1.8" strokeLinecap="round"><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v4h4"/><path d="M9 12h6M9 15.5h6"/></svg>;
97	}
98	function IcoPause({ c = C.navy }: { c?: string }) {
99	  return <svg width={17} height={17} viewBox="0 0 24 24" fill={c}><rect x="6.5" y="4.5" width="3.6" height="15" rx="1.3"/><rect x="13.9" y="4.5" width="3.6" height="15" rx="1.3"/></svg>;
100	}
101	
102	const STAT_ICONS = [IcoTenants, IcoWarn, IcoPage, IcoPause];
103	
104	export default function PropertyDashboard() {
105	  const [, setLocation] = useLocation();
106	
107	  const { data: tenants = [] } = useQuery<any[]>({
108	    queryKey: ['/api/property/tenants'],
109	    queryFn: () => propFetch('/api/property/tenants').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
110	    staleTime: 60000,
111	    retry: false,
112	  });
113	
114	  const { data: invoices = [], isLoading: invLoading, isError: invError, refetch: refetchInv } = useQuery<any[]>({
115	    queryKey: ['/api/property/invoices'],
116	    queryFn: () => propFetch('/api/property/invoices').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
117	    staleTime: 30000,
118	    retry: false,
119	  });
120	
121	  const { data: schedules = [] } = useQuery<any[]>({
122	    queryKey: ['/api/property/schedules'],
123	    queryFn: () => propFetch('/api/property/schedules').then(r => { if (!r.ok) throw new Error('load failed'); return r.json(); }),
124	    staleTime: 60000,
125	    retry: false,
126	  });
127	
128	  /* Derived stats — voided invoices are excluded from collection/recent so a
129	     cancelled request never drags down the rate or shows as a live payment. */
130	  const liveInvoices    = invoices.filter((i: any) => i.status !== 'voided');
131	  const activeTenants   = tenants.filter((t: any) => t.status !== 'archived').length;
132	  const overdueCount    = invoices.filter((i: any) => i.status === 'overdue').length;
133	  const queuedCount     = invoices.filter((i: any) => i.status === 'pending_dispatch').length;
134	  const activeCount     = invoices.filter((i: any) => ['pending_dispatch', 'dispatched', 'overdue', 'dispatch_failed'].includes(i.status)).length;
135	  const paidCount       = liveInvoices.filter((i: any) => i.status === 'paid' || i.status === 'paid_external').length;
136	  const collectionPct   = liveInvoices.length > 0 ? paidCount / liveInvoices.length : 0;
137	
138	  const now = new Date();
139	  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
140	  const monthlyRevenue = invoices
141	    .filter((i: any) => (i.status === 'paid' || i.status === 'paid_external') && i.paidAt && new Date(i.paidAt) >= monthStart)
142	    .reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
143	
144	  const recent = [...liveInvoices]
145	    .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
146	    .slice(0, 3);
147	
148	  const stats = [
149	    { label: 'tenants',     v: activeTenants, Ico: STAT_ICONS[0] },
150	    { label: 'outstanding', v: overdueCount,  Ico: STAT_ICONS[1] },
151	    { label: 'queued',      v: queuedCount,   Ico: STAT_ICONS[2] },
152	    { label: 'paused',      v: schedules.filter((s: any) => s.status === 'paused').length, Ico: STAT_ICONS[3] },
153	  ];
154	
155	  return (
156	    <div style={{ background: C.white, minHeight: '100svh', display: 'flex', justifyContent: 'center' }}>
157	    <div style={{ width: '100%', maxWidth: 430, minHeight: '100svh', background: '#F4F4F4', paddingBottom: 130, fontFamily: "'Outfit', system-ui, sans-serif" }}>
158	      <div style={{ height: 54 }} />
159	
160	      {/* Load error — show a retry instead of silently rendering zeros */}
161	      {invError && (
162	        <div style={{ margin: '0 18px 12px', padding: '14px 16px', borderRadius: 16, background: 'rgba(255,59,78,0.08)', border: '1px solid rgba(255,59,78,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12 }}>
163	          <span style={{ color: '#C71A2A', fontSize: 13, fontWeight: 500 }}>{invLoading ? 'loading…' : "couldn't load your data"}</span>
164	          <button onClick={() => refetchInv()} style={{ background: C.navy, color: C.white, border: 'none', borderRadius: 10, padding: '8px 14px', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}>retry</button>
165	        </div>
166	      )}
167	
168	      {/* 1 — Active transaction hero */}
169	      <PopIn index={0}>
170	      <div style={{ padding: '0 18px' }}>
171	        <motion.div {...HOVER} style={{ background: C.navy, borderRadius: 24, padding: '24px 26px 26px', cursor: 'default' }}>
172	          <div style={{ fontWeight: 900, fontSize: 62, color: C.sky, letterSpacing: '-0.04em', lineHeight: 0.92, fontVariantNumeric: 'tabular-nums' }}>
173	            {activeCount}
174	          </div>
175	          <div style={{ fontWeight: 500, fontSize: 12, color: C.sky, letterSpacing: '0.16em', textTransform: 'uppercase', marginTop: 6 }}>
176	            active transaction{activeCount !== 1 ? 's' : ''}
177	          </div>
178	          <div style={{ marginTop: 18, height: 24, borderRadius: 999, border: `1.5px solid ${C.sky}`, padding: 3 }}>
179	            <div style={{ width: `${Math.max(4, collectionPct * 100)}%`, height: '100%', borderRadius: 999, background: C.sky, transition: 'width 0.8s ease' }} />
180	          </div>
181	        </motion.div>
182	      </div>
183	      </PopIn>
184	
185	      {/* 2 — Revenue + gauge row */}
186	      <PopIn index={1}>
187	      <div style={{ display: 'grid', gridTemplateColumns: '1.32fr 1fr', gap: 14, padding: '16px 18px 0' }}>
188	        <motion.div {...HOVER} style={{ background: C.sky, borderRadius: 22, padding: '24px 22px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
189	          <div style={{ fontWeight: 900, fontSize: 36, color: C.navy, letterSpacing: '-0.04em', lineHeight: 1, fontVariantNumeric: 'tabular-nums' }}>
190	            {fmtCents(monthlyRevenue)}
191	          </div>
192	          <div style={{ fontWeight: 500, fontSize: 11, color: C.navy, letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: 12, lineHeight: 1.3 }}>
193	            monthly rent<br />revenue
194	          </div>
195	        </motion.div>
196	        <motion.div {...HOVER} style={{ background: '#F2F0F0', borderRadius: 22, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
197	          <Ring pct={collectionPct} />
198	        </motion.div>
199	      </div>
200	      </PopIn>
201	
202	      {/* 3 — Stat carousel */}
203	      <PopIn index={2}><StatCarousel stats={stats} /></PopIn>
204	
205	      {/* 4 — Rent transactions */}
206	      <PopIn index={3}>
207	      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '22px 20px 12px' }}>
208	        <div style={{ fontWeight: 600, fontSize: 12, color: C.navy, letterSpacing: '0.12em', textTransform: 'uppercase' }}>rent transactions</div>
209	        <button onClick={() => setLocation('/property/tenants')} style={{ fontSize: 13, fontWeight: 600, color: C.btn, background: 'none', border: 'none', cursor: 'pointer' }}>view all →</button>
210	      </div>
211	
212	      {recent.length === 0 ? (
213	        <div style={{ padding: '32px 18px', textAlign: 'center', color: C.mute, fontSize: 13 }}>
214	          no transactions yet — add tenants to get started
215	        </div>
216	      ) : (
217	        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, padding: '0 18px' }}>
218	          {recent.map((inv: any) => {
219	            const name     = inv.tenantName || '—';
220	            const initials = name.split(' ').map((w: string) => w[0]).join('').slice(0, 2).toUpperCase();
221	            return (
222	              <motion.div key={inv.id} {...HOVER} style={{ ...GLASS, borderRadius: 18, padding: '14px 16px', display: 'flex', alignItems: 'center', gap: 13, cursor: 'pointer' }}>
223	                <div style={{ width: 40, height: 40, borderRadius: 999, background: C.navy, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, fontWeight: 800, fontSize: 12, color: C.sky, letterSpacing: '0.03em' }}>
224	                  {initials}
225	                </div>
226	                <div style={{ flex: 1, minWidth: 0 }}>
227	                  <div style={{ fontWeight: 500, fontSize: 13.5, color: C.navy, textTransform: 'capitalize', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</div>
228	                  <div style={{ fontWeight: 400, fontSize: 11, color: C.mute, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{inv.propertyAddress || '—'}</div>
229	                </div>
230	                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 5, flexShrink: 0 }}>
231	                  {(() => {
232	                    const isSplit = inv.splitEnabled && inv.splitCount > 1;
233	                    const paid = inv.splitPaidCount || 0;
234	                    const showOwing = isSplit && paid > 0 && invoiceStatus(inv) !== 'paid';
235	                    return (
236	                      <>
237	                        <div style={{ fontWeight: 700, fontSize: 14, color: C.navy, fontVariantNumeric: 'tabular-nums' }}>{fmtCents(showOwing ? (inv.owingCents ?? inv.amountCents) : (inv.amountCents ?? 0))}</div>
238	                        {isSplit && <div style={{ fontSize: 9.5, fontWeight: 700, color: '#0B7D63' }}>{paid}/{inv.splitCount} split</div>}
239	                      </>
240	                    );
241	                  })()}
242	                  <StatusBox status={invoiceStatus(inv)} />
243	                </div>
244	              </motion.div>
245	            );
246	          })}
247	        </div>
248	      )}
249	      </PopIn>
250	    </div>
251	    </div>
252	  );
253	}
